package com.landportal.controller; import com.landportal.repository.UserRepository; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/profile") public class ProfileController{final UserRepository repo;public ProfileController(UserRepository r){repo=r;}@GetMapping public Object me(Authentication a){var u=repo.findByEmail(a.getName()).orElseThrow();return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"phone",u.getPhone()==null?"":u.getPhone(),"role",u.getRole(),"active",u.isActive());}}
